class TaskManager {
private:
    struct Task {
        int userId, taskId, priority;
        bool operator<(const Task& other) const {
            if (priority != other.priority) return priority > other.priority;
            return taskId > other.taskId;
        }
    };
    unordered_map<int, pair<int, int>> taskMap;
    set<Task> taskSet;

public:
    TaskManager(vector<vector<int>>& tasks) {
        for (const auto& t : tasks) {
            add(t[0], t[1], t[2]);
        }
    }

    void add(int userId, int taskId, int priority) {
        taskMap[taskId] = {userId, priority};
        taskSet.insert({userId, taskId, priority});
    }

    void edit(int taskId, int newPriority) {
        auto it = taskMap.find(taskId);
        if (it != taskMap.end()) {
            int userId = it->second.first;
            int oldPriority = it->second.second;
            taskSet.erase({userId, taskId, oldPriority});
            taskMap[taskId] = {userId, newPriority};
            taskSet.insert({userId, taskId, newPriority});
        }
    }

    void rmv(int taskId) {
        auto it = taskMap.find(taskId);
        if (it != taskMap.end()) {
            int userId = it->second.first;
            int priority = it->second.second;
            taskSet.erase({userId, taskId, priority});
            taskMap.erase(it);
        }
    }

    int execTop() {
        if (taskSet.empty()) return -1;
        auto topIt = taskSet.begin();
        int userId = topIt->userId;
        int taskId = topIt->taskId;
        taskSet.erase(topIt);
        taskMap.erase(taskId);
        return userId;
    }
};

class TaskManager {
    static class Task implements Comparable<Task> {
        int userId, taskId, priority;
        Task(int userId, int taskId, int priority) {
            this.userId = userId;
            this.taskId = taskId;
            this.priority = priority;
        }
        @Override
        public int compareTo(Task o) {
            if (this.priority != o.priority) return Integer.compare(o.priority, this.priority);
            return Integer.compare(o.taskId, this.taskId);
        }
    }

    private Map<Integer, Task> map;
    private TreeSet<Task> set;

    public TaskManager(List<List<Integer>> tasks) {
        map = new HashMap<>();
        set = new TreeSet<>();
        for (List<Integer> t : tasks) {
            add(t.get(0), t.get(1), t.get(2));
        }
    }

    public void add(int userId, int taskId, int priority) {
        Task t = new Task(userId, taskId, priority);
        map.put(taskId, t);
        set.add(t);
    }

    public void edit(int taskId, int newPriority) {
        Task old = map.get(taskId);
        if (old != null) {
            set.remove(old);
            Task next = new Task(old.userId, taskId, newPriority);
            map.put(taskId, next);
            set.add(next);
        }
    }

    public void rmv(int taskId) {
        Task old = map.remove(taskId);
        if (old != null) {
            set.remove(old);
        }
    }

    public int execTop() {
        if (set.isEmpty()) return -1;
        Task top = set.pollFirst();
        map.remove(top.taskId);
        return top.userId;
    }
}

class TaskManager {
    constructor(tasks) {
        this.taskMap = new Map();
        this.tasks = [];
        for (const [userId, taskId, priority] of tasks) {
            this.add(userId, taskId, priority);
        }
    }

    add(userId, taskId, priority) {
        this.taskMap.set(taskId, { userId, priority });
        this.tasks.push({ userId, taskId, priority });
    }

    edit(taskId, newPriority) {
        const item = this.taskMap.get(taskId);
        if (item) {
            item.priority = newPriority;
            this.tasks.push({ userId: item.userId, taskId, priority: newPriority });
        }
    }

    rmv(taskId) {
        this.taskMap.delete(taskId);
    }

    execTop() {
        this.tasks.sort((a, b) => b.priority !== a.priority ? b.priority - a.priority : b.taskId - a.taskId);
        while (this.tasks.length > 0) {
            const top = this.tasks.shift();
            const current = this.taskMap.get(top.taskId);
            if (current && current.priority === top.priority && current.userId === top.userId) {
                this.taskMap.delete(top.taskId);
                return top.userId;
            }
        }
        return -1;
    }
}
